export function youtubeThumbnail(id: string) {
  return thumb(id);
}

export function youtubeEmbedSrc(id: string, opts?: { autoplay?: boolean; mute?: boolean }) {
  const autoplay = opts?.autoplay ? "1" : "0";
  const mute = opts?.mute === false ? "0" : "1";
  const params = new URLSearchParams({
    rel: "0",
    modestbranding: "1",
    playsinline: "1",
    mute,
    autoplay,
  });
  return `https://www.youtube-nocookie.com/embed/${id}?${params.toString()}`;
}

export function getYoutubeUpload(id: string) {
  return youtubeUploads.find((v) => v.id === id);
}

export function isBroadcastShelf(tapeId: string) {
  return tapeId === "t-broadcast";
}
